-- =========================================================
--  BANKING DATASET
--  Database: Banking_System
--  Tables: branches, customers, accounts, cards, transactions,
--          loans, loan_payments, fixed_deposits
--  Notes: synthetic data; the transaction ledger is consistent
--         (balance_after follows every deposit, withdrawal and
--         transfer, never goes negative, and equals accounts.balance
--         for the last row of each account); internal transfers are
--         stored as a Transfer Out / Transfer In pair that point to
--         each other through related_account_id; closed accounts end
--         with a zero balance and have no later activity; dormant
--         accounts have no activity in the last 12 months; loan
--         payments follow an amortization schedule; loans and fixed
--         deposits exist only for KYC-verified customers;
--         UNIQUE constraints on branch_name, ifsc_code, email,
--         account_number
--  Amounts are in INR. loan_payments are recorded separately and are
--  not mirrored in the transactions table.
-- =========================================================

CREATE DATABASE IF NOT EXISTS Banking_System;
USE Banking_System;

-- ---------------------------------------------------------
-- BRANCHES TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS branches (
    branch_id INT PRIMARY KEY,
    branch_name VARCHAR(80) NOT NULL UNIQUE,
    city VARCHAR(50),
    state VARCHAR(50),
    ifsc_code VARCHAR(15) NOT NULL UNIQUE,
    opened_date DATE
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- CUSTOMERS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
    customer_id INT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    gender VARCHAR(10),
    date_of_birth DATE,
    email VARCHAR(100) NOT NULL UNIQUE,
    phone VARCHAR(20),
    city VARCHAR(50),
    occupation VARCHAR(30),
    kyc_status VARCHAR(20),
    join_date DATE
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- ACCOUNTS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS accounts (
    account_id INT PRIMARY KEY,
    account_number VARCHAR(12) NOT NULL UNIQUE,
    customer_id INT NOT NULL,
    branch_id INT NOT NULL,
    account_type VARCHAR(20),
    open_date DATE,
    status VARCHAR(20),
    closed_date DATE NULL,
    balance DECIMAL(14 , 2 ),
    FOREIGN KEY (customer_id)
        REFERENCES customers (customer_id),
    FOREIGN KEY (branch_id)
        REFERENCES branches (branch_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- CARDS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS cards (
    card_id INT PRIMARY KEY,
    account_id INT NOT NULL,
    card_type VARCHAR(10),
    card_network VARCHAR(15),
    card_last4 CHAR(4),
    issue_date DATE,
    expiry_date DATE,
    credit_limit DECIMAL(12 , 2 ) NULL,
    status VARCHAR(15),
    FOREIGN KEY (account_id)
        REFERENCES accounts (account_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- TRANSACTIONS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS transactions (
    transaction_id INT PRIMARY KEY,
    account_id INT NOT NULL,
    transaction_date DATETIME,
    transaction_type VARCHAR(20),
    amount DECIMAL(14 , 2 ),
    balance_after DECIMAL(14 , 2 ),
    channel VARCHAR(20),
    description VARCHAR(100),
    related_account_id INT NULL,
    FOREIGN KEY (account_id)
        REFERENCES accounts (account_id),
    FOREIGN KEY (related_account_id)
        REFERENCES accounts (account_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- LOANS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS loans (
    loan_id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    branch_id INT NOT NULL,
    loan_type VARCHAR(20),
    principal_amount DECIMAL(14 , 2 ),
    interest_rate DECIMAL(5 , 2 ),
    tenure_months INT,
    emi_amount DECIMAL(12 , 2 ),
    start_date DATE,
    status VARCHAR(20),
    FOREIGN KEY (customer_id)
        REFERENCES customers (customer_id),
    FOREIGN KEY (branch_id)
        REFERENCES branches (branch_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- LOAN_PAYMENTS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS loan_payments (
    payment_id INT PRIMARY KEY,
    loan_id INT NOT NULL,
    due_date DATE,
    payment_date DATE,
    amount_paid DECIMAL(12 , 2 ),
    principal_paid DECIMAL(12 , 2 ),
    interest_paid DECIMAL(12 , 2 ),
    payment_status VARCHAR(15),
    FOREIGN KEY (loan_id)
        REFERENCES loans (loan_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;

-- ---------------------------------------------------------
-- FIXED_DEPOSITS TABLE
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS fixed_deposits (
    fd_id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    branch_id INT NOT NULL,
    principal_amount DECIMAL(14 , 2 ),
    interest_rate DECIMAL(5 , 2 ),
    start_date DATE,
    tenure_months INT,
    maturity_date DATE,
    maturity_amount DECIMAL(14 , 2 ),
    status VARCHAR(15),
    FOREIGN KEY (customer_id)
        REFERENCES customers (customer_id),
    FOREIGN KEY (branch_id)
        REFERENCES branches (branch_id)
)  ENGINE=INNODB DEFAULT CHARSET=UTF8MB4;


